// Compile-time check that src/builtin.inc matches src/builtin.jq
// byte-for-byte, except that "$$$$" in builtin.jq corresponds to "$"
// in the .inc.  Fails to compile with Mismatch<byte-offset> on error.
#include <cstddef>

static constexpr char jq_builtins[] =
#include "src/builtin.inc"
;

static constexpr unsigned char expected[] = {
#embed "src/builtin.jq"
};

constexpr size_t NPOS = static_cast<size_t>(-1);

constexpr size_t mismatch_at() {
  size_t j = 0;
  for (size_t i = 0; i < sizeof(expected); i++, j++) {
    if (expected[i] == '$' && i + 3 < sizeof(expected) &&
        expected[i+1] == '$' && expected[i+2] == '$' && expected[i+3] == '$')
      i += 3;
    if (j >= sizeof(jq_builtins) - 1) return i;
    if (static_cast<unsigned char>(jq_builtins[j]) != expected[i]) return i;
  }
  if (jq_builtins[j] != '\0') return sizeof(expected);
  return NPOS;
}

template<size_t N> struct Mismatch;
template<> struct Mismatch<NPOS> { static const int ok = 1; };
static const int ok = Mismatch<mismatch_at()>::ok;

